#!/usr/bin/env venv-run
"""Generate host/ta_event_bodies.gen.h from TaskEvent Python SoT."""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

from taskevent.types import EVENT_CLASSES


def render_bodies() -> str:
    lines: list[str] = [
        "/* Generated by taskevent/gen_c_header.py -- do not edit by hand. */",
        "#ifndef SPINME_TA_EVENT_BODIES_GEN_H",
        "#define SPINME_TA_EVENT_BODIES_GEN_H",
        "",
        "#include <stdint.h>",
        "",
        "/* Body structs only; enums/envelope live in ta_event.h. */",
        "",
    ]
    seen: set[str] = set()
    for cls in EVENT_CLASSES:
        name = cls.c_type_name
        if name in seen or name == "uint8_t":
            continue
        seen.add(name)
        lines.append(f"/* {cls.type_name} type_id={cls.type_id:#x} */")
        lines.append(cls.to_c_struct().rstrip())
        lines.append("")
    lines.append("#endif /* SPINME_TA_EVENT_BODIES_GEN_H */")
    lines.append("")
    return "\n".join(lines)


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument(
        "-o",
        "--output",
        type=Path,
        default=Path(__file__).resolve().parents[1] / "host" / "ta_event_bodies.gen.h",
    )
    ap.add_argument(
        "--check",
        action="store_true",
        help="exit 1 if output path would change (bit-identical check)",
    )
    args = ap.parse_args(argv)
    text = render_bodies()
    if args.check:
        if not args.output.is_file():
            print(f"missing {args.output}", file=sys.stderr)
            return 1
        existing = args.output.read_text(encoding="ascii")
        if existing != text:
            print(f"drift: {args.output} != Python SoT", file=sys.stderr)
            return 1
        print(f"ok bit-identical {args.output}")
        return 0
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(text, encoding="ascii")
    print(f"wrote {args.output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
